import{z as l,x as p,o as r,c as o,q as s,j as i,D as A,d as a,s as t,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"移动安全","description":"","frontmatter":{"title":"移动安全","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ss-mobile.md","filePath":"cs/ss-mobile.md","lastUpdated":1791413859000}'),d={name:"cs/ss-mobile.md"};function c(D,E,m,h,u,C){const B=p("Mermaid");return r(),o("div",null,[E[2]||(E[2]=s('<h1 id="移动安全" tabindex="-1">移动安全 <a class="header-anchor" href="#移动安全" aria-label="Permalink to &quot;移动安全&quot;">​</a></h1><div class="epigraph"><p>手机把「一人一机」改成了「一机百 App」；安全的重心从守住一台机器，变成在它身上划几十个互不相认的格子。</p><footer>—— 据 Enck et al., Understanding Android Security, IEEE S&amp;P 2009；Apple Platform Security 文档整理</footer></div><p><a href="/cs/ss-hardware-perspective">上一课</a>把硬件同时当根信任与攻击面；手机是这套东西最普及的兑现——每部手机出厂自带启动链、TEE 与按 App 划好的格子。本课把移动当体系课的标本写：内核沙箱、权限模型与更新链条三件套，如何把前面七课的机制压进一台贴身的设备。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>桌面威胁模型默认一人一机、装什么自己担责；手机把这个前提翻了过来：一台设备上几十个 App 互不相认，安装第三方代码是常态而非例外，传感器贴着人——位置、相机、麦克风、生物特征，泄露的后果直接落在个体身上。缺口是：在「不可信 App 是常态」的前提下，平台怎么划格子、怎么管入口、怎么补洞。这三问分别对应沙箱（第 2 课）、供应链（第 3 课）与补丁窗口（主干课）在移动平台的具体形态。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="格子、入口与补洞" tabindex="-1">格子、入口与补洞 <a class="header-anchor" href="#格子、入口与补洞" aria-label="Permalink to &quot;格子、入口与补洞&quot;">​</a></h3><p>格子：Android 给每个 App 分配一个独立的 Linux UID——沙箱不是新机制，就是内核讲过的用户隔离直接复用，再让 SELinux 的 MAC 盖一层，把即便被攻破的 App 也按类型域限权；iOS 走另一条路：代码必须经平台签名才能运行，沙箱 profile 收紧系统调用与文件面。入口：权限模型把敏感能力（定位、联系人、相机）收进受控中介，安装时声明、运行时逐项授予；应用商店审核是<a href="/cs/ss-supply-chain">供应链站点图</a>的消费端门，重打包与仿冒 App 是这门没守住的典型样本。补洞：更新链条决定 N-day 窗口——Android 的「芯片厂到 OEM 到运营商」层级让补丁到达时间碎片化，把主干补丁管理课的窗口在移动端拉长；iOS 的统一推送把窗口压短到全设备同步。</p><p><span class="marginnote">Android 4.4（2013）先对少数守护进程启用 SELinux enforcing，5.0（2014）扩到整个平台；每个 App 的 UID 由 zygote 派生——「给每个应用一个用户」是 2009 年 Enck 等总结的平台核心设计，沿用至今。据 Android 平台安全文档整理。</span></p><p><span class="marginnote">「每个 App 一个 UID」翻译成大白话：操作系统把每个应用当成一台机器上互不相干的「不同用户」来管——A 用户读不到 B 用户的文件，正如银行 App 读不到相册。权限弹窗是第二道闸，管的是「这个用户是否被允许用相机」；两道闸各管各的，叠加才构成移动平台的格子。</span></p>',10)),(r(),i(n,null,{default:A(()=>[t(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22App%EF%BC%9A%E4%B8%8D%E5%8F%AF%E4%BF%A1%E6%98%AF%E5%B8%B8%E6%80%81%22%5D%20--%3E%20UID%5B%22UID%20%E6%B2%99%E7%AE%B1%EF%BC%9A%E5%86%85%E6%A0%B8%E7%94%A8%E6%88%B7%E9%9A%94%E7%A6%BB%E5%A4%8D%E7%94%A8%22%5D%0A%20%20UID%20--%3E%20MAC%5B%22SELinux%20MAC%EF%BC%9A%E7%B1%BB%E5%9E%8B%E5%9F%9F%E9%99%90%E6%9D%83%22%5D%0A%20%20PERM%5B%22%E6%9D%83%E9%99%90%E6%A8%A1%E5%9E%8B%EF%BC%9A%E8%BF%90%E8%A1%8C%E6%97%B6%E9%80%90%E9%A1%B9%E6%8E%88%E4%BA%88%22%5D%20--%3E%20APP%0A%20%20STORE%5B%22%E5%95%86%E5%BA%97%E5%AE%A1%E6%A0%B8%EF%BC%9A%E4%BE%9B%E5%BA%94%E9%93%BE%E6%B6%88%E8%B4%B9%E7%AB%AF%E9%97%A8%22%5D%20--%3E%20APP%0A%20%20MAC%20--%3E%20KERN%5B%22Linux%20%E5%86%85%E6%A0%B8%22%5D%0A%20%20KERN%20--%3E%20HW%5B%22TEE%20%E4%B8%8E%E5%90%AF%E5%8A%A8%E9%93%BE%EF%BC%9A%E5%AF%86%E9%92%A5%E4%B8%8E%E7%B3%BB%E7%BB%9F%E5%88%86%E5%8C%BA%E4%B8%8B%E6%B2%89%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("为什么格子之下还要硬件：第 2 课的逻辑原样成立——所有格子共享同一面内核墙，"),e("a",{href:"/cs/ss-kernel-vuln-classes"},"内核漏洞类别"),a("表对每个格子都成立；于是敏感资产再沉一层：密钥与生物特征比对进 TEE 的安全世界，启动链校验系统分区，远程证明把设备状态讲给服务端。这就是"),e("a",{href:"/cs/ss-hardware-perspective"},"硬件视角"),a("「信任有根」的消费级落地。攻方的经济学随之定型：对贴身设备，社会工程比重写内核便宜——重打包、仿冒、stalkerware 攻的是格子之间的人，不是格子本身；平台对策也相应从技术单点转向链条纵深。")],-1)),(r(),i(n,null,{default:A(()=>[t(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20PATCH%5B%22%E5%8E%82%E5%95%86%E5%8F%91%E5%B8%83%E5%AE%89%E5%85%A8%E8%A1%A5%E4%B8%81%22%5D%20--%3E%20SOC%5B%22%E8%8A%AF%E7%89%87%E5%8E%82%EF%BC%9ASoC%20%E4%B8%8E%E9%A9%B1%E5%8A%A8%E9%80%82%E9%85%8D%22%5D%0A%20%20SOC%20--%3E%20OEM%5B%22OEM%EF%BC%9A%E6%9C%BA%E5%9E%8B%E9%80%82%E9%85%8D%E4%B8%8E%E6%B5%8B%E8%AF%95%22%5D%0A%20%20OEM%20--%3E%20CARRIER%5B%22%E8%BF%90%E8%90%A5%E5%95%86%EF%BC%9A%E5%AE%9A%E5%88%B6%E4%B8%8E%E6%94%BE%E8%A1%8C%22%5D%0A%20%20CARRIER%20--%3E%20AND%5B%22Android%20%E8%AE%BE%E5%A4%87%EF%BC%9A%E9%80%90%E7%BA%A7%E5%BB%B6%E8%BF%9F%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20IOS%5B%22iOS%EF%BC%9A%E5%8E%82%E5%95%86%E7%9B%B4%E8%BE%BE%E7%9A%84%E7%BB%9F%E4%B8%80%E6%8E%A8%E9%80%81%22%5D%20--%3E%20IOSDEV%5B%22%E5%85%A8%E8%AE%BE%E5%A4%87%E5%90%8C%E6%97%A5%E5%88%B0%E8%BE%BE%22%5D%0A%20%20AND%20--%3E%20LONG%5B%22N-day%20%E7%AA%97%E5%8F%A3%E9%95%BF%E4%B8%94%E7%A2%8E%E7%89%87%E5%8C%96%22%5D%0A%20%20IOSDEV%20--%3E%20SHORT%5B%22N-day%20%E7%AA%97%E5%8F%A3%E7%9F%AD%E4%B8%94%E5%90%8C%E6%AD%A5%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=s('<p><span class="marginnote">N-day 窗口就是「补丁已存在」到「你的设备已打上」之间的时间差。直觉类比：安卓的更新像批发转零售——批发价（补丁）当天出，经过芯片厂、厂商、运营商层层加价（适配与放行）才到你手里；iOS 是厂商直营店，同一批货全网同天上架。链条每多一级，全世界的攻击窗口就多几周。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>TEE 与启动链的机制细节专课已讲，本课只借其结论；App 层的 Web 漏洞（XSS 等）已有专课；企业管控（MDM）与合规不展开。移动端侧信道与固件层问题分别归硬件课与固件课，此处不重讲。</p><p><span class="marginnote">常见误区：以为「点了允许」的权限越少就越安全。权限模型管的是 App 正常运行时的能力，管不住被攻破的进程——App 一旦被内存漏洞打穿，攻击者继承的是这个 UID 的全部文件面，而不是弹窗里那几项。所以格子的强度上限由内核与 TEE 决定，权限弹窗只是入口的一层减速带。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>移动翻转了桌面前提：不可信 App 是常态，传感器贴身，泄露直接伤及个体。</li><li>三件套：UID 沙箱加 MAC 划格子、权限模型与商店管入口、更新链条定补洞窗口。</li><li>格子共享一面内核墙，所以密钥与证明下沉 TEE——硬件信任根的消费级落地。</li><li>攻方经济学：贴身设备上社会工程便宜，重打包与 stalkerware 攻人攻链，不攻格子。</li><li>出处：Enck et al., IEEE S&amp;P 2009；Android 平台安全文档；Apple Platform Security；对照 <a href="/cs/selinux-type-enforcement">selinux-type-enforcement</a>。</li></ul>',6))])}const S=l(d,[["render",c]]);export{F as __pageData,S as default};
